);

T_RESET_CHECK_IDLE: assert property (@(posedge clock) disable iff (reset)
    $past(reset) |-> ((chk_state == INS_IDLE) && (chk_crc == 32'hFFFFFFFF) && !o_val && !chk_tval && !bad_fcs)
);

T_RESET_CHECK_DELAY_LINE_INVALID: assert property (@(posedge clock) disable iff (reset)
    $past(reset) |-> (!chk_v0 && !chk_v1 && !chk_v2 && !chk_v3)
);

T_RESET_SOURCE_PORT_NOT_READY: assert property (@(posedge clock) disable iff (reset)
    $past(reset) |-> !s_rdy
);

T_RESET_SHIFT_REGISTER_EMPTY: assert property (@(posedge clock) disable iff (reset)
    $past(reset) |-> ((sr_valid == 16'd0) && !m_val)
);

T_RESET_AW_TRACKING_EMPTY: assert property (@(posedge clock) disable iff (reset)
    $past(reset) |-> ((awf_fill == 4'd0) && (awf_wr == awf_rd) && !cid_valid)
);

T_RESET_BOTH_SLAVE_PORTS_READY: assert property (@(posedge clock) disable iff (reset)
    $past(reset) |-> (aw_rdy && w_rdy)
);
